mapper.select:
select mc.*, u.name as memberName, u.phone, coalesce(d.name, s.name) as goodsName from member_comment mc left join user u on mc.user_id = u.id left join dish d on mc.dish_id = d.id left join setmeal s on mc.setmeal_id = s.id
and u.name like concat('%', #{memberName}, '%')
and coalesce(d.name, s.name) like concat('%', #{goodsName}, '%')
and mc.rating = #{rating}
and mc.status = #{status}
order by mc.create_time desc
